pub fn run<I, S>(args: I) -> CliOutput
where
    I: IntoIterator<Item = S>,
    S: Into<String>,
{
    with_process_context_lock(|| run_unlocked(args))
}

fn run_unlocked<I, S>(args: I) -> CliOutput
where
    I: IntoIterator<Item = S>,
    S: Into<String>,
{
    let _process_context = match ProcessContextSnapshot::capture() {
        Ok(snapshot) => snapshot,
        Err(error) => {
            return command_error(
                "process_context_failed",
                &format!("could not capture process context: {error}"),
            );
        }
    };
    let mut args = args.into_iter().map(Into::into).collect::<Vec<_>>();
    if args.is_empty() {
        args.push(BIN_NAME.to_string());
    }

    let (globals, rest) = match parse_global_options(&args[1..]) {
        Ok(parsed) => parsed,
        Err(error) => return command_error("invalid_global_options", &error),
    };
    if let Some(repo) = &globals.repo {
        if let Err(error) = std::env::set_current_dir(repo) {
            return command_error(
                "invalid_global_options",
                &format!("--repo could not be used as current directory: {error}"),
            );
        }
        std::env::set_var(GLOBAL_REPO_SOURCE_ENV, "global --repo");
    } else {
        std::env::remove_var(GLOBAL_REPO_SOURCE_ENV);
    }
    if let Some(db) = &globals.db {
        let resolved_db = absolutize_path(db).unwrap_or_else(|_| db.to_path_buf());
        std::env::set_var("CODEGRAPH_DB_PATH", &resolved_db);
        std::env::set_var(GLOBAL_DB_SOURCE_ENV, "global --db");
    } else if std::env::var_os("CODEGRAPH_DB_PATH").is_some() {
        std::env::set_var(GLOBAL_DB_SOURCE_ENV, "env CODEGRAPH_DB_PATH");
    } else {
        std::env::remove_var(GLOBAL_DB_SOURCE_ENV);
    }

    let rest = rest.as_slice();
    if rest.is_empty() || matches!(rest[0].as_str(), "--help" | "-h") {
        return success(help_text());
    }

    if matches!(rest[0].as_str(), "--version" | "-V") {
        return success(if globals.json {
            json_line(build_metadata_json())
        } else {
            format!(
                "{BIN_NAME} {} ({})\n",
                env!("CARGO_PKG_VERSION"),
                build_commit()
            )
        });
    }

    let command_name = rest[0].as_str();
    let Some(command) = COMMANDS.iter().find(|spec| spec.name == command_name) else {
        return structured_error("unknown_command", command_name);
    };

    let mut command_args = rest[1..].to_vec();
    if globals.profile
        && matches!(command.name, "index" | "context-pack" | "context")
        && !command_args.iter().any(|arg| arg == "--profile")
    {
        command_args.push("--profile".to_string());
    }
    if globals.verbose
        && command.name == "index"
        && !command_args.iter().any(|arg| arg == "--verbose")
    {
        command_args.push("--verbose".to_string());
    }
    if globals.json
        && matches!(
            command.name,
            "index" | "agent-use" | "query" | "doctor" | "languages" | "config" | "status"
        )
        && !command_args.iter().any(|arg| arg == "--json")
    {
        command_args.push("--json".to_string());
    }
    if globals.agent_json {
        if !matches!(command.name, "query" | "context-pack" | "context") {
            return command_error(
                "invalid_global_options",
                &format!(
                    "--agent-json can only be used before query or context-pack: {BIN_NAME} --agent-json query ..."
                ),
            );
        }
        if !command_args
            .iter()
            .any(|arg| matches!(arg.as_str(), "--agent-json" | "--agent_json"))
        {
            command_args.push("--agent-json".to_string());
        }
    }
    if let Some(limit) = globals.limit {
        match command.name {
            "query" => {
                if !has_flag_with_value(&command_args, "--limit") {
                    command_args.push("--limit".to_string());
                    command_args.push(limit.to_string());
                }
            }
            "context-pack" | "context" => {
                if !has_flag_with_value(&command_args, "--limit-paths") {
                    command_args.push("--limit-paths".to_string());
                    command_args.push(limit.to_string());
                }
                if !has_flag_with_value(&command_args, "--limit-snippets") {
                    command_args.push("--limit-snippets".to_string());
                    command_args.push(limit.to_string());
                }
            }
            _ => {
                return command_error(
                    "invalid_global_options",
                    &format!(
                        "--limit can only be used before query or context-pack: {BIN_NAME} --limit <n> query ..."
                    ),
                );
            }
        }
    }
    if command_args
        .iter()
        .any(|arg| matches!(arg.as_str(), "--help" | "-h"))
    {
        return success(command_help_text(command));
    }

    match command.name {
        "init" => run_json_command("init_failed", run_init_command(&command_args)),
        "index" => run_json_command("index_failed", run_index_command(&command_args)),
        "agent-use" => run_json_command("agent_use_failed", run_agent_use_command(&command_args)),
        "status" => run_json_command("status_failed", run_status_command(&command_args)),
        "query" => run_json_command("query_failed", run_query_command(&command_args)),
        "impact" => run_json_command("impact_failed", run_impact_command(&command_args)),
        "context-pack" | "context" => run_json_command(
            "context_pack_failed",
            run_context_pack_command(&command_args),
        ),
        "bundle" => run_json_command("bundle_failed", run_bundle_command(&command_args)),
        "watch" => run_watch_command(&command_args),
        "serve-mcp" | "mcp" => run_serve_mcp_command(&command_args),
        "serve-ui" | "ui" => run_serve_ui_command(&command_args),
        "bench" => run_json_command("bench_failed", run_bench_command(&command_args)),
        "trace" => run_json_command("trace_failed", run_trace_command(&command_args)),
        "audit" => run_json_command("audit_failed", audit::run_audit_command(&command_args)),
        "languages" => run_languages_command(&command_args),
        "doctor" => run_json_command("doctor_failed", run_doctor_command(&command_args)),
        "config" => run_json_command("config_failed", run_config_command(&command_args)),
        _ => success(not_implemented_json(command, &command_args)),
    }
}

fn run_json_command(error_kind: &str, result: Result<Value, String>) -> CliOutput {
    match result {
        Ok(value) if error_kind == "bench_failed" => {
            success(json_line(add_benchmark_binary_metadata(value)))
        }
        Ok(value) => success(json_line(value)),
        Err(error) if error_kind == "bench_failed" => command_error_json(
            error_kind,
            add_benchmark_binary_metadata(serde_json::from_str::<Value>(&error).unwrap_or_else(
                |_| {
                    json!({
                        "status": "error",
                        "error": error_kind,
                        "message": error,
                    })
                },
            )),
        ),
        Err(error) => match serde_json::from_str::<Value>(&error) {
            Ok(value) => command_error_json(error_kind, value),
            Err(_) => command_error(error_kind, &error),
        },
    }
}

fn parse_global_options(args: &[String]) -> Result<(GlobalOptions, Vec<String>), String> {
    let mut globals = GlobalOptions::default();
    let mut rest = Vec::new();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--repo" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--repo requires a path".to_string());
                };
                globals.repo = Some(PathBuf::from(value));
            }
            "--db" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--db requires a path".to_string());
                };
                globals.db = Some(PathBuf::from(value));
            }
            "--json" => globals.json = true,
            "--agent-json" | "--agent_json" => globals.agent_json = true,
            "--limit" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--limit requires a value".to_string());
                };
                globals.limit = Some(parse_limit_value(value)?);
            }
            value if value.starts_with("--limit=") => {
                let value = value.trim_start_matches("--limit=");
                globals.limit = Some(parse_limit_value(value)?);
            }
            "--no-color" => globals.no_color = true,
            "--verbose" => globals.verbose = true,
            "--quiet" => globals.quiet = true,
            "--profile" => globals.profile = true,
            value => {
                rest.extend(args[index..].iter().cloned());
                if value.is_empty() {
                    return Err("empty command".to_string());
                }
                break;
            }
        }
        index += 1;
    }
    Ok((globals, rest))
}

fn has_flag_with_value(args: &[String], flag: &str) -> bool {
    args.iter()
        .any(|arg| arg == flag || arg.starts_with(&format!("{flag}=")))
}

fn canonical_global_flag(arg: &str) -> Option<&'static str> {
    match arg {
        "--repo" => Some("--repo"),
        "--db" => Some("--db"),
        "--json" => Some("--json"),
        "--no-color" => Some("--no-color"),
        "--verbose" => Some("--verbose"),
        "--quiet" => Some("--quiet"),
        "--profile" => Some("--profile"),
        _ if arg.starts_with("--repo=") => Some("--repo"),
        _ if arg.starts_with("--db=") => Some("--db"),
        _ => None,
    }
}

fn misplaced_global_flag_message(flag: &str, command_name: &str) -> String {
    let value_hint = match flag {
        "--repo" | "--db" => " <path>",
        _ => "",
    };
    format!(
        "{flag} is a global flag. Put it before the command: {BIN_NAME} {flag}{value_hint} {command_name} ..."
    )
}

fn misplaced_global_flag_error(arg: &str, command_name: &str) -> Option<String> {
    canonical_global_flag(arg).map(|flag| misplaced_global_flag_message(flag, command_name))
}

fn success(stdout: String) -> CliOutput {
    CliOutput {
        exit_code: 0,
        stdout,
        stderr: String::new(),
    }
}

fn structured_error(kind: &str, value: &str) -> CliOutput {
    CliOutput {
        exit_code: 2,
        stdout: String::new(),
        stderr: json_line(json!({
            "status": "error",
            "error": kind,
            "value": value,
            "message": format!("Run '{BIN_NAME} --help' for supported commands."),
        })),
    }
}

fn command_error(kind: &str, message: &str) -> CliOutput {
    CliOutput {
        exit_code: 1,
        stdout: String::new(),
        stderr: json_line(json!({
            "status": "error",
            "error": kind,
            "message": message,
        })),
    }
}

fn command_error_json(kind: &str, mut value: Value) -> CliOutput {
    if let Some(object) = value.as_object_mut() {
        object
            .entry("status".to_string())
            .or_insert_with(|| json!("error"));
        object
            .entry("error".to_string())
            .or_insert_with(|| json!(kind));
    }
    CliOutput {
        exit_code: 1,
        stdout: String::new(),
        stderr: json_line(value),
    }
}

fn help_text() -> String {
    let mut output = String::from(
        "CodeGraph Memory Layer CLI\n\n\
         Usage:\n  codegraph-mcp <COMMAND> [ARGS]\n  codegraph-mcp --help\n\n\
         Global flags:\n  --repo <path>  --db <path>  --json  --no-color  --verbose  --quiet  --profile\n\n\
         Commands:\n",
    );

    for command in COMMANDS {
        output.push_str(&format!("  {:<13} {}\n", command.name, command.description));
    }

    output.push_str(
        "\nPhase 30: proof-focused UI/MCP ergonomics, real-repo corpus manifests, and honest parity reporting are available without weakening proof labels.\n\
         Workflow rule: no subagents; single-agent use only.\n",
    );

    output
}

fn run_init_command(args: &[String]) -> Result<Value, String> {
    let options = parse_init_options(args)?;
    let repo_root = resolve_repo_root(&options.repo)?;
    let languages = detect_tooling(&repo_root)?;
    let codegraph_dir = repo_root.join(".codegraph");
    let codex_dir = repo_root.join(".codex");
    let config_path = codex_dir.join("config.toml");
    let skills_dir = codex_dir.join("skills");
    let hooks_dir = codex_dir.join("hooks");
    let mut actions = vec![json!({
        "action": "create_dir",
        "path": path_string(&codegraph_dir),
    })];

    if options.with_codex_config {
        actions.push(json!({
            "action": "create_file_if_missing",
            "path": path_string(&config_path),
            "template": "mcp_servers.codegraph-mcp",
        }));
    }
    if options.with_agents {
        actions.push(json!({
            "action": "create_file_if_missing",
            "path": path_string(&repo_root.join("AGENTS.md")),
            "template": "single-agent CodeGraph instructions",
        }));
    }
    if options.with_skills {
        actions.push(json!({
            "action": "create_dir",
            "path": path_string(&skills_dir),
            "templates": template_names(SKILL_TEMPLATES),
        }));
    }
    if options.with_hooks {
        actions.push(json!({
            "action": "create_dir",
            "path": path_string(&hooks_dir),
            "templates": template_names(HOOK_TEMPLATES),
        }));
    }
    if options.run_index {
        actions.push(json!({
            "action": "run_index",
            "repo": path_string(&repo_root),
        }));
    }

    let mut index_summary = None;
    if !options.dry_run {
        fs::create_dir_all(&codegraph_dir).map_err(|error| error.to_string())?;
        if options.with_codex_config || options.with_skills || options.with_hooks {
            fs::create_dir_all(&codex_dir).map_err(|error| error.to_string())?;
        }
        if options.with_codex_config {
            write_if_missing(&config_path, &codex_config_template(&repo_root))?;
        }
        if options.with_agents {
            write_if_missing(&repo_root.join("AGENTS.md"), agents_template())?;
        }
        if options.with_skills {
            fs::create_dir_all(&skills_dir).map_err(|error| error.to_string())?;
            write_template_files(&skills_dir, SKILL_TEMPLATES)?;
        }
        if options.with_hooks {
            fs::create_dir_all(&hooks_dir).map_err(|error| error.to_string())?;
            write_template_files(&hooks_dir, HOOK_TEMPLATES)?;
        }
        if options.run_index {
            index_summary = Some(index_repo(&repo_root).map_err(|error| error.to_string())?);
        }
    }

    Ok(json!({
        "status": if options.dry_run { "dry_run" } else { "initialized" },
        "phase": PHASE,
        "repo_root": path_string(&repo_root),
        "detected": languages,
        "actions": actions,
        "index_summary": index_summary,
        "next_commands": [
            "codegraph-mcp index .",
            "codegraph-mcp status",
            "codegraph-mcp query symbols <query>",
            "codegraph-mcp query callers <symbol>",
            "codegraph-mcp context-pack --task <task>"
        ],
        "workflow": "single-agent-only",
    }))
}

fn run_index_command(args: &[String]) -> Result<Value, String> {
    let (repo, db, mut options, output_mode, budget_options, vector_index_options) =
        parse_index_command_options(args)?;
    let started = Instant::now();
    let repo_root = resolve_repo_root(Path::new(&repo))?;
    let db_path = db
        .clone()
        .map(|path| normalize_db_path_for_repo(&repo_root, &path))
        .unwrap_or_else(|| selected_db_path_for_repo(&repo_root).path);
    let vector_index_path = vector_index_options.runtime_path.as_ref().map(|path| {
        if path.is_absolute() {
            path.clone()
        } else {
            std::env::current_dir()
                .unwrap_or_else(|_| PathBuf::from("."))
                .join(path)
        }
    });
    let vector_audit_artifact_path =
        vector_index_options
            .audit_artifact_path
            .as_ref()
            .map(|path| {
                if path.is_absolute() {
                    path.clone()
                } else {
                    std::env::current_dir()
                        .unwrap_or_else(|_| PathBuf::from("."))
                        .join(path)
                }
            });
    let candidate_spool_path = options.candidate_spool_path.as_ref().map(|path| {
        if path.is_absolute() {
            path.clone()
        } else {
            std::env::current_dir()
                .unwrap_or_else(|_| PathBuf::from("."))
                .join(path)
        }
    });
    options.candidate_spool_path = candidate_spool_path.clone();
    let mut candidate_spool_budget_decision =
        apply_candidate_spool_budget_policy(&mut options, &budget_options, &vector_index_options);
    if options.candidate_spool_required
        && candidate_spool_budget_decision.disabled_reason.is_some()
        && matches!(
            candidate_spool_budget_decision.decision.as_str(),
            "candidate_spool_required_budget_exceeded"
                | "candidate_spool_required_without_path"
                | "candidate_spool_policy_off"
        )
    {
        return Err(
            serde_json::to_string(&candidate_spool_required_error_value(
                &candidate_spool_budget_decision,
                false,
                false,
                "candidate spool was marked required but cannot be built under the requested policy/budget",
            ))
            .map_err(|error| error.to_string())?,
        );
    }
    let candidate_spool_path = options.candidate_spool_path.clone();
    let preflight = storage_budget::storage_budget_preflight(
        &budget_options,
        storage_budget::StorageBudgetContext {
            command: "codegraph-mcp index".to_string(),
            repo_root: Some(repo_root.clone()),
            db_path: Some(db_path.clone()),
            out_path: vector_index_path.clone().or(candidate_spool_path.clone()),
            explicit_db: db.is_some(),
            explicit_out: vector_index_path.is_some()
                || vector_audit_artifact_path.is_some()
                || candidate_spool_path.is_some(),
            diagnostic_only: false,
        },
    );
    if preflight.is_refused() {
        return Err(storage_budget::structured_error_string(
            storage_budget::storage_budget_error_value("codegraph-mcp index", &preflight),
        ));
    }
    let mut summary = if let Some(db) = db {
        index_repo_to_db_with_options(Path::new(&repo), &db, options)
    } else {
        index_repo_with_options(Path::new(&repo), options)
    }
    .map_err(|error| error.to_string())?;
    let vector_index_summary = if let Some(vector_index_path) = vector_index_path.as_ref() {
        let provider = context_pack_vector_provider()?;
        let vector_summary = build_vector_chunk_index_artifacts_for_repo(
            &repo_root,
            &db_path,
            vector_index_path,
            &provider,
            context_pack_vector_build_options(),
            VectorChunkIndexArtifactOptions {
                runtime_format: vector_index_options.runtime_format,
                audit_artifact_path: vector_audit_artifact_path.clone(),
            },
        )
        .map_err(|error| error.to_string())?;
        add_index_profile_span_ms_to_summary(
            &mut summary,
            "vector_runtime_sidecar_build",
            vector_summary.build_timings.total_ms,
            1,
            vector_summary.persisted_total_chunks as u64,
            "runtime vector sidecar build total from vector build summary",
        );
        if vector_audit_artifact_path.is_some() {
            add_index_profile_span_ms_to_summary(
                &mut summary,
                "vector_audit_artifact_build",
                vector_summary.build_timings.write_json_ms,
                1,
                vector_summary.audit_total_chunks as u64,
                "audit artifact write is measured inside aggregate vector write_json_ms; runtime/audit write split is not yet separable",
            );
        }
        refresh_index_profile_derived_fields(&mut summary);
        Some(vector_summary)
    } else {
        None
    };
    let wall_ms = started.elapsed().as_secs_f64() * 1000.0;
    let mut vector_outputs = vector_index_path
        .iter()
        .chain(vector_audit_artifact_path.iter())
        .cloned()
        .collect::<Vec<PathBuf>>();
    if candidate_spool_budget_decision.required {
        if let Some(path) = candidate_spool_path.as_ref() {
            vector_outputs.push(path.clone());
            vector_outputs.push(candidate_spool_query_index_path(path));
        }
    }
    let budget = storage_budget::storage_budget_postflight(preflight, &[db_path], &vector_outputs);
    let max_artifact_bytes = artifact_budget_bytes(&budget_options);
    let hard_artifact_bytes = budget.artifact_bytes.unwrap_or(0);
    let artifact_budget_remaining_bytes = max_artifact_bytes.saturating_sub(hard_artifact_bytes);
    candidate_spool_budget_decision.artifact_budget_remaining_bytes =
        Some(artifact_budget_remaining_bytes);
    let spool_footprint_bytes = candidate_spool_footprint_bytes(&summary);
    let runtime_sidecar_ready = vector_index_summary
        .as_ref()
        .is_some_and(|summary| summary.status == "ok" || summary.status == "ready");
    if let Some(spool) = summary.candidate_spool.as_mut() {
        spool.candidate_spool_required = candidate_spool_budget_decision.required;
        spool.candidate_spool_policy = candidate_spool_budget_decision.policy.as_str().to_string();
        spool.candidate_spool_budget_bytes =
            candidate_spool_budget_decision.budget_bytes.unwrap_or(0);
        spool.artifact_budget_remaining_bytes = Some(artifact_budget_remaining_bytes);
        if spool_footprint_bytes > artifact_budget_remaining_bytes {
            spool.candidate_spool_truncated = true;
            spool.candidate_spool_partial = true;
            spool.artifact_budget_decision =
                Some("candidate_spool_exceeds_remaining_budget".to_string());
            spool.candidate_spool_warning = Some(
                "Candidate spool footprint exceeded remaining artifact budget; graph DB/runtime outputs remain governed by their own validation.".to_string(),
            );
        } else {
            spool.artifact_budget_decision = Some(candidate_spool_budget_decision.decision.clone());
            spool.candidate_spool_warning = candidate_spool_budget_decision.warning.clone();
        }
        spool.candidate_spool_disabled_reason =
            candidate_spool_budget_decision.disabled_reason.clone();
    }
    let mut value = match output_mode {
        IndexJsonOutputMode::Audit => index_summary_json(&summary),
        IndexJsonOutputMode::Agent => index_summary_agent_json(&summary, wall_ms),
        IndexJsonOutputMode::Concise => index_summary_concise_json(&summary, wall_ms),
    }?;
    if let Some(object) = value.as_object_mut() {
        if let Some(vector_index_summary) = vector_index_summary {
            object.insert(
                "vector_index".to_string(),
                serde_json::to_value(vector_index_summary).map_err(|error| error.to_string())?,
            );
            object.insert("external_provider".to_string(), json!(false));
            object.insert("source_leaves_machine".to_string(), json!(false));
        }
        if output_mode == IndexJsonOutputMode::Agent {
            let budget_json = budget.to_json();
            object.insert(
                "storage_budget".to_string(),
                json!({
                    "budget_status": budget_json.get("budget_status").cloned().unwrap_or(Value::Null),
                    "claimable": budget_json.get("claimable").cloned().unwrap_or(Value::Null),
                    "db_bytes": budget_json.get("db_bytes").cloned().unwrap_or(Value::Null),
                    "artifact_bytes": budget_json.get("artifact_bytes").cloned().unwrap_or(Value::Null),
                    "refusal_reason": budget_json.get("refusal_reason").cloned().unwrap_or(Value::Null),
                }),
            );
        } else {
            object.insert("storage_budget".to_string(), budget.to_json());
        }
        apply_candidate_spool_budget_json_fields(
            object,
            &summary,
            &candidate_spool_budget_decision,
            spool_footprint_bytes,
            index_summary_claimable(&summary),
            runtime_sidecar_ready,
        );
        if output_mode == IndexJsonOutputMode::Agent {
            object.remove("candidate_spool_budget");
            if let Some(summary) = object.get_mut("summary").and_then(Value::as_object_mut) {
                summary.remove("candidate_spool_budget");
            }
        }
    }
    if budget.is_refused() {
        if candidate_spool_budget_decision.required {
            return Err(serde_json::to_string(&candidate_spool_required_error_value(
                &candidate_spool_budget_decision,
                index_summary_claimable(&summary),
                runtime_sidecar_ready,
                budget.refusal_reason.clone().unwrap_or_else(|| {
                    "candidate spool required and storage budget refused".to_string()
                }),
            ))
            .map_err(|error| error.to_string())?);
        }
        return Err(storage_budget::structured_error_string(
            storage_budget::storage_budget_error_value("codegraph-mcp index", &budget),
        ));
    }
    Ok(value)
}

fn run_agent_use_command(args: &[String]) -> Result<Value, String> {
    let Some(subcommand) = args.first() else {
        return Err(
            "Usage: codegraph-mcp agent-use <status|index|query|context-pack|mcp-config|watch> --repo <repo> --json"
                .to_string(),
        );
    };
    match subcommand.as_str() {
        "status" => run_agent_use_status_command(&args[1..]),
        "index" => run_agent_use_index_command(&args[1..]),
        "query" => run_agent_use_query_command(&args[1..]),
        "context-pack" | "context" => run_agent_use_context_pack_command(&args[1..]),
        "mcp-config" | "mcp_config" => run_agent_use_mcp_config_command(&args[1..]),
        "watch" => run_agent_use_watch_command(&args[1..]),
        other => Err(format!(
            "unknown agent-use command: {other}; expected status, index, query, context-pack, mcp-config, or watch"
        )),
    }
}

#[derive(Debug, Clone)]
struct AgentUseBasicOptions {
    repo: PathBuf,
    detail_mode: AgentUseDetailMode,
    max_output_bytes: Option<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentUseDetailMode {
    Compact,
    Explain,
    Audit,
}

impl AgentUseDetailMode {
    fn preserves_full_details(self) -> bool {
        !matches!(self, AgentUseDetailMode::Compact)
    }

    fn default_max_output_bytes(self) -> usize {
        if self.preserves_full_details() {
            DEFAULT_AGENT_USE_EXPLAIN_MAX_OUTPUT_BYTES
        } else {
            DEFAULT_AGENT_USE_AGENT_JSON_MAX_OUTPUT_BYTES
        }
    }
}

#[derive(Debug, Clone)]
struct AgentUseIndexOptions {
    repo: PathBuf,
    passthrough_index_args: Vec<String>,
}

#[derive(Debug, Clone)]
struct AgentUseWatchOptions {
    repo: PathBuf,
    once: bool,
    changed_paths: Vec<PathBuf>,
    test_events: Vec<PathBuf>,
    debounce: Duration,
    max_updates: Option<usize>,
    idle_timeout: Option<Duration>,
    lock_retries: usize,
    lock_retry: Duration,
    max_batch_paths: usize,
}

#[derive(Debug, Clone)]
struct AgentUseForwardOptions {
    repo: PathBuf,
    forwarded_args: Vec<String>,
}

fn parse_agent_use_basic_args(
    args: &[String],
    subcommand: &str,
) -> Result<AgentUseBasicOptions, String> {
    let mut repo = None;
    let mut detail_mode = AgentUseDetailMode::Compact;
    let mut max_output_bytes = None;
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--json" | "--agent-json" | "--agent_json" => {}
            "--explain" => {
                detail_mode = AgentUseDetailMode::Explain;
            }
            "--verbose" => {
                if detail_mode == AgentUseDetailMode::Compact {
                    detail_mode = AgentUseDetailMode::Explain;
                }
            }
            "--audit-json" | "--audit_json" => {
                detail_mode = AgentUseDetailMode::Audit;
            }
            "--max-output-bytes" | "--max-bytes" | "--max_output_bytes" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--max-output-bytes requires a value".to_string());
                };
                max_output_bytes = Some(parse_context_pack_max_output_bytes(value)?);
            }
            "--repo" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--repo requires a path".to_string());
                };
                repo = Some(PathBuf::from(value));
            }
            "--db" => {
                return Err(format!(
                    "agent-use {subcommand} owns DB resolution through the production profile; --db is not accepted"
                ));
            }
            value if value.starts_with('-') => {
                return Err(format!("unknown agent-use {subcommand} option: {value}"));
            }
            value => {
                if repo.is_some() {
                    return Err(format!(
                        "Usage: codegraph-mcp agent-use {subcommand} --repo <repo> --json"
                    ));
                }
                repo = Some(PathBuf::from(value));
            }
        }
        index += 1;
    }
    Ok(AgentUseBasicOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        detail_mode,
        max_output_bytes,
    })
}

fn parse_agent_use_index_args(args: &[String]) -> Result<AgentUseIndexOptions, String> {
    let mut repo = None;
    let mut passthrough_index_args = Vec::new();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--json" | "--agent-json" | "--agent_json" => {}
            "--repo" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--repo requires a path".to_string());
                };
                repo = Some(PathBuf::from(value));
            }
            "--db" => {
                return Err(
                    "agent-use index owns DB resolution through the production profile; --db is not accepted"
                        .to_string(),
                );
            }
            "--fresh"
            | "--rebuild"
            | "--incremental"
            | "--fail-on-db-problem"
            | "--allow-stale-reuse"
            | "--profile" => {
                passthrough_index_args.push(args[index].clone());
            }
            "--workers"
            | "--storage-mode"
            | "--build-mode"
            | "--max-db-mib"
            | "--max-artifacts-mib"
            | "--min-free-disk-gib" => {
                let flag = args[index].clone();
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err(format!("{flag} requires a value"));
                };
                passthrough_index_args.push(flag);
                passthrough_index_args.push(value.clone());
            }
            value if value.starts_with('-') => {
                return Err(format!(
                    "unknown agent-use index option: {value}; use plain index with explicit --db for advanced sidecar/scope flags"
                ));
            }
            value => {
                if repo.is_some() {
                    return Err(
                        "Usage: codegraph-mcp agent-use index --repo <repo> [--fresh|--rebuild|--incremental] [--json]".to_string(),
                    );
                }
                repo = Some(PathBuf::from(value));
            }
        }
        index += 1;
    }
    Ok(AgentUseIndexOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        passthrough_index_args,
    })
}

fn parse_agent_use_watch_args(args: &[String]) -> Result<AgentUseWatchOptions, String> {
    let mut repo = None;
    let mut once = false;
    let mut changed_paths = Vec::new();
    let mut test_events = Vec::new();
    let mut debounce = Duration::from_millis(AGENT_USE_WATCH_DEFAULT_DEBOUNCE_MS);
    let mut max_updates = None;
    let mut idle_timeout = None;
    let mut lock_retries = AGENT_USE_WATCH_DEFAULT_LOCK_RETRIES;
    let mut lock_retry = Duration::from_millis(AGENT_USE_WATCH_DEFAULT_LOCK_RETRY_MS);
    let mut max_batch_paths = AGENT_USE_WATCH_DEFAULT_MAX_BATCH_PATHS;
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--json" | "--agent-json" | "--agent_json" => {}
            "--repo" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--repo requires a path".to_string());
                };
                repo = Some(PathBuf::from(value));
            }
            "--db" => {
                return Err(
                    "agent-use watch owns DB resolution through the production profile; --db is not accepted"
                        .to_string(),
                );
            }
            "--once" => once = true,
            "--changed" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--changed requires a path".to_string());
                };
                changed_paths.push(PathBuf::from(value));
            }
            "--test-event" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--test-event requires a path".to_string());
                };
                test_events.push(PathBuf::from(value));
            }
            "--debounce-ms" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--debounce-ms requires a value".to_string());
                };
                debounce = Duration::from_millis(parse_u64_arg("--debounce-ms", value)?);
            }
            "--max-updates" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--max-updates requires a value".to_string());
                };
                max_updates = Some(parse_usize_arg("--max-updates", value)?);
            }
            "--idle-timeout-ms" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--idle-timeout-ms requires a value".to_string());
                };
                idle_timeout = Some(Duration::from_millis(parse_u64_arg(
                    "--idle-timeout-ms",
                    value,
                )?));
            }
            "--lock-retries" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--lock-retries requires a value".to_string());
                };
                lock_retries = parse_usize_arg("--lock-retries", value)?;
            }
            "--lock-retry-ms" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--lock-retry-ms requires a value".to_string());
                };
                lock_retry = Duration::from_millis(parse_u64_arg("--lock-retry-ms", value)?);
            }
            "--max-batch-paths" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--max-batch-paths requires a value".to_string());
                };
                max_batch_paths = parse_usize_arg("--max-batch-paths", value)?;
            }
            value if value.starts_with('-') => {
                return Err(format!(
                    "unknown agent-use watch option: {value}; supported shapes are `agent-use watch --repo <repo> --json` and `agent-use watch --repo <repo> --once --changed <path> [--changed <path>] --json`"
                ));
            }
            value => {
                if repo.is_some() {
                    return Err(
                        "Usage: codegraph-mcp agent-use watch --repo <repo> --json [--debounce-ms <ms>] or codegraph-mcp agent-use watch --repo <repo> --once --changed <path> [--changed <path>] --json"
                            .to_string(),
                    );
                }
                repo = Some(PathBuf::from(value));
            }
        }
        index += 1;
    }
    Ok(AgentUseWatchOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        once,
        changed_paths,
        test_events,
        debounce,
        max_updates,
        idle_timeout,
        lock_retries,
        lock_retry,
        max_batch_paths,
    })
}

fn parse_u64_arg(flag: &str, value: &str) -> Result<u64, String> {
    value
        .parse::<u64>()
        .map_err(|error| format!("{flag} must be an integer: {error}"))
}

fn parse_usize_arg(flag: &str, value: &str) -> Result<usize, String> {
    value
        .parse::<usize>()
        .map_err(|error| format!("{flag} must be an integer: {error}"))
}

fn parse_agent_use_forward_args(
    args: &[String],
    subcommand: &str,
) -> Result<AgentUseForwardOptions, String> {
    let mut repo = None;
    let mut forwarded_args = Vec::new();
    let mut literal_args = false;
    let mut index = 0usize;
    while index < args.len() {
        if literal_args {
            forwarded_args.push(args[index].clone());
            index += 1;
            continue;
        }
        match args[index].as_str() {
            "--" => {
                literal_args = true;
                forwarded_args.push(args[index].clone());
            }
            "--repo" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--repo requires a path".to_string());
                };
                repo = Some(PathBuf::from(value));
            }
            "--db" => {
                return Err(format!(
                    "agent-use {subcommand} owns DB resolution through the production profile; --db is not accepted"
                ));
            }
            value => forwarded_args.push(value.to_string()),
        }
        index += 1;
    }
    Ok(AgentUseForwardOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        forwarded_args,
    })
}

fn agent_use_forward_detail_mode(args: &[String]) -> AgentUseDetailMode {
    let mut mode = AgentUseDetailMode::Compact;
    for arg in args {
        match arg.as_str() {
            "--audit-json" | "--audit_json" => return AgentUseDetailMode::Audit,
            "--explain" | "--debug" => mode = AgentUseDetailMode::Explain,
            "--verbose" if mode == AgentUseDetailMode::Compact => {
                mode = AgentUseDetailMode::Explain
            }
            _ => {}
        }
    }
    mode
}

fn strip_agent_use_query_wrapper_flags(
    args: Vec<String>,
) -> Result<(Vec<String>, AgentUseDetailMode, Option<usize>), String> {
    let detail_mode = agent_use_forward_detail_mode(&args);
    let mut max_output_bytes = None;
    let mut stripped = Vec::new();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--max-output-bytes" | "--max-bytes" | "--max_output_bytes" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--max-output-bytes requires a value".to_string());
                };
                max_output_bytes = Some(parse_context_pack_max_output_bytes(value)?);
            }
            value
                if value.starts_with("--max-output-bytes=")
                    || value.starts_with("--max-bytes=")
                    || value.starts_with("--max_output_bytes=") =>
            {
                let value = value
                    .split_once('=')
                    .map(|(_, value)| value)
                    .unwrap_or_default();
                max_output_bytes = Some(parse_context_pack_max_output_bytes(value)?);
            }
            "--explain" | "--verbose" | "--audit-json" | "--audit_json" => {}
            _ => stripped.push(args[index].clone()),
        }
        index += 1;
    }
    Ok((stripped, detail_mode, max_output_bytes))
}

fn agent_use_context_max_output_bytes(args: &[String], detail_mode: AgentUseDetailMode) -> usize {
    context_pack_forwarded_max_output_bytes(args)
        .unwrap_or_else(|| detail_mode.default_max_output_bytes())
}

fn ensure_context_pack_max_output_arg(args: &mut Vec<String>, max_output_bytes: usize) {
    if context_pack_forwarded_max_output_bytes(args).is_none() {
        args.push("--max-output-bytes".to_string());
        args.push(max_output_bytes.to_string());
    }
}

fn query_args_request_agent_json(args: &[String]) -> bool {
    args.iter()
        .any(|arg| matches!(arg.as_str(), "--agent-json" | "--agent_json" | "--concise"))
}

fn context_args_request_agent_json(args: &[String]) -> bool {
    args.iter().any(|arg| {
        matches!(
            arg.as_str(),
            "--agent-json" | "--agent_json" | "--concise" | "--audit-json" | "--audit_json"
        )
    })
}

fn context_args_have_vector_controls(args: &[String]) -> bool {
    args.iter().any(|arg| {
        matches!(
            arg.as_str(),
            "--enable-vector-candidates"
                | "--enable_vector_candidates"
                | "--vector-index"
                | "--vector-index-path"
                | "--vector_index"
                | "--vector_index_path"
                | "--vector-runtime-sidecar"
                | "--vector_runtime_sidecar"
        )
    })
}

fn agent_use_index_args_have_lifecycle_policy(args: &[String]) -> bool {
    args.iter().any(|arg| {
        matches!(
            arg.as_str(),
            "--fresh"
                | "--rebuild"
                | "--incremental"
                | "--fail-on-db-problem"
                | "--allow-stale-reuse"
        )
    })
}

fn agent_use_index_should_auto_fresh_rebuild(preflight: &DbLifecyclePreflight) -> bool {
    if preflight.safe || preflight.path_access_status == "db_missing" {
        return false;
    }
    if preflight
        .blockers
        .iter()
        .any(|blocker| blocker.contains("previous run did not complete"))
    {
        return true;
    }
    matches!(
        preflight.db_problem_kind.as_deref(),
        Some(
            "schema_mismatch"
                | "repo_head_mismatch"
                | "passport_missing"
                | "scope_mismatch"
                | "storage_mismatch"
        )
    )
}

fn cli_write_path_chaos_failpoint_enabled(name: &str) -> bool {
    std::env::var(WRITE_PATH_CHAOS_FAILPOINT_ENV)
        .ok()
        .is_some_and(|raw| {
            raw.split(',')
                .map(str::trim)
                .any(|value| value == name || value == "agent_use_profile_all")
        })
}

fn run_agent_use_query_command(args: &[String]) -> Result<Value, String> {
    let options = parse_agent_use_forward_args(args, "query")?;
    let Some(query_kind) = options.forwarded_args.first().cloned() else {
        return Err(
            "Usage: codegraph-mcp agent-use query <symbols|text|files|references|definitions|callers|callees|path|chain|unresolved-calls> <args> --repo <repo> --limit <n> --agent-json"
                .to_string(),
        );
    };
    if !agent_use_query_kind_supported(query_kind.as_str()) {
        return Err(format!(
            "agent-use query supports symbols, text, files, references, definitions, callers, callees, path, chain, and unresolved-calls; got {query_kind}"
        ));
    }
    let (mut forwarded_args, detail_mode, max_output_bytes) =
        strip_agent_use_query_wrapper_flags(options.forwarded_args)?;
    let max_output_bytes =
        max_output_bytes.unwrap_or_else(|| detail_mode.default_max_output_bytes());
    let profile = resolve_agent_use_profile(&options.repo)?;
    let normal_dot_codegraph = profile.repo_root.join(".codegraph");
    let normal_dot_codegraph_existed_before = normal_dot_codegraph.exists();
    let preflight = inspect_read_db_lifecycle_preflight(
        &profile.repo_root,
        &profile.db_path,
        Some(profile.scope_policy.clone()),
    )?;
    if !preflight.safe {
        let mut value = agent_use_unavailable_json(
            &profile,
            &preflight,
            "query",
            Some(query_kind.as_str()),
            None,
            normal_dot_codegraph_existed_before,
        );
        compact_agent_use_agent_json_envelope(
            &mut value,
            &profile,
            detail_mode,
            max_output_bytes,
            None,
        );
        return Ok(value);
    }

    if !query_args_request_agent_json(&forwarded_args) {
        if query_kind == "unresolved-calls" {
            forwarded_args.push("--json".to_string());
        } else {
            forwarded_args.push("--agent-json".to_string());
        }
    }
    let mut value =
        with_agent_use_profile_context(&profile, || run_query_command(&forwarded_args))?;
    annotate_agent_use_output(
        &mut value,
        &profile,
        "query",
        normal_dot_codegraph_existed_before,
    );
    add_agent_use_db_lifecycle_read(&mut value, &preflight);
    add_agent_use_durability_labels(&mut value, &profile, &preflight, None);
    add_agent_use_query_read_path_metrics(&mut value, query_kind.as_str());
    compact_agent_use_agent_json_envelope(
        &mut value,
        &profile,
        detail_mode,
        max_output_bytes,
        None,
    );
    Ok(value)
}

fn agent_use_query_kind_supported(kind: &str) -> bool {
    matches!(
        kind,
        "symbols"
            | "text"
            | "files"
            | "references"
            | "definitions"
            | "callers"
            | "callees"
            | "path"
            | "chain"
            | "unresolved-calls"
    )
}

fn run_agent_use_context_pack_command(args: &[String]) -> Result<Value, String> {
    let options = parse_agent_use_forward_args(args, "context-pack")?;
    let profile = resolve_agent_use_profile(&options.repo)?;
    let normal_dot_codegraph = profile.repo_root.join(".codegraph");
    let normal_dot_codegraph_existed_before = normal_dot_codegraph.exists();
    let preflight = inspect_read_db_lifecycle_preflight(
        &profile.repo_root,
        &profile.db_path,
        Some(profile.scope_policy.clone()),
    )?;
    let mut forwarded_args = options.forwarded_args;
    let detail_mode = agent_use_forward_detail_mode(&forwarded_args);
    let max_output_bytes = agent_use_context_max_output_bytes(&forwarded_args, detail_mode);
    ensure_context_pack_max_output_arg(&mut forwarded_args, max_output_bytes);
    if !context_args_request_agent_json(&forwarded_args) {
        forwarded_args.push("--agent-json".to_string());
    }
    if preflight.safe {
        if profile.vector_runtime_path.exists()
            && !context_args_have_vector_controls(&forwarded_args)
        {
            forwarded_args.push("--enable-vector-candidates".to_string());
            forwarded_args.push("--vector-runtime-sidecar".to_string());
            forwarded_args.push(path_string(&profile.vector_runtime_path));
        }
        let mut value =
            with_agent_use_profile_context(&profile, || run_context_pack_command(&forwarded_args))?;
        annotate_agent_use_output(
            &mut value,
            &profile,
            "context-pack",
            normal_dot_codegraph_existed_before,
        );
        add_agent_use_db_lifecycle_read(&mut value, &preflight);
        add_agent_use_staged_availability(&mut value, &profile, &preflight);
        let staged_availability = value
            .get("staged_availability")
            .cloned()
            .unwrap_or_else(|| {
                staged_availability_for_cli(
                    &profile.repo_root,
                    &profile.db_path,
                    Some(&preflight),
                    Some(&profile.candidate_spool_path),
                    Some(&profile.vector_runtime_path),
                    Some(&profile.vector_audit_path),
                    None,
                )
            });
        add_agent_use_rtds_freshness_fields(&mut value, &profile, &preflight, &staged_availability);
        add_agent_use_durability_labels(&mut value, &profile, &preflight, None);
        add_agent_use_context_pack_read_path_metrics(&mut value);
        // Compact the agent-use-specific heavy sections (recovery, lifecycle,
        // read_path_metrics, etc.) BEFORE the context-pack size enforcer runs.
        // Otherwise the enforcer sees a transiently-oversized envelope and sheds
        // contract-required sections (patch_assist_packet) that would have fit
        // once the agent-use compaction shrank the rest.
        compact_agent_use_agent_json_envelope(
            &mut value,
            &profile,
            detail_mode,
            max_output_bytes,
            Some(&staged_availability),
        );
        enforce_agent_use_context_pack_max_output_bytes(&mut value, max_output_bytes);
        return Ok(value);
    }

    if preflight.path_access_status == "db_missing" && profile.candidate_spool_path.exists() {
        if !forwarded_args.iter().any(|arg| {
            matches!(
                arg.as_str(),
                "--candidate-spool"
                    | "--candidate_spool"
                    | "--early-candidates"
                    | "--early_candidates"
            )
        }) {
            forwarded_args.push("--candidate-spool".to_string());
            forwarded_args.push(path_string(&profile.candidate_spool_path));
            forwarded_args.push("--early-candidates".to_string());
        }
        return match with_agent_use_profile_context(&profile, || {
            run_context_pack_command(&forwarded_args)
        }) {
            Ok(mut value) => {
                annotate_agent_use_output(
                    &mut value,
                    &profile,
                    "context-pack",
                    normal_dot_codegraph_existed_before,
                );
                if let Some(object) = value.as_object_mut() {
                    object.insert(
                        "db_lifecycle_read".to_string(),
                        db_lifecycle_preflight_json(&preflight, true, false, false),
                    );
                }
                add_agent_use_durability_labels(&mut value, &profile, &preflight, None);
                let staged_availability =
                    value
                        .get("staged_availability")
                        .cloned()
                        .unwrap_or_else(|| {
                            staged_availability_for_cli(
                                &profile.repo_root,
                                &profile.db_path,
                                Some(&preflight),
                                Some(&profile.candidate_spool_path),
                                Some(&profile.vector_runtime_path),
                                Some(&profile.vector_audit_path),
                                None,
                            )
                        });
                add_agent_use_rtds_freshness_fields(
                    &mut value,
                    &profile,
                    &preflight,
                    &staged_availability,
                );
                add_agent_use_context_pack_read_path_metrics(&mut value);
                // Compact agent-use-specific heavy sections before the context
                // enforcer so it does not shed contract-required patch_assist_packet
                // from a transiently-oversized envelope (matches the safe-DB path).
                compact_agent_use_agent_json_envelope(
                    &mut value,
                    &profile,
                    detail_mode,
                    max_output_bytes,
                    Some(&staged_availability),
                );
                enforce_agent_use_context_pack_max_output_bytes(&mut value, max_output_bytes);
                Ok(value)
            }
            Err(error) => {
                let mut value = agent_use_unavailable_json(
                    &profile,
                    &preflight,
                    "context-pack",
                    None,
                    Some(error),
                    normal_dot_codegraph_existed_before,
                );
                let staged_availability = value.get("staged_availability").cloned();
                compact_agent_use_agent_json_envelope(
                    &mut value,
                    &profile,
                    detail_mode,
                    max_output_bytes,
                    staged_availability.as_ref(),
                );
                Ok(value)
            }
        };
    }

    let mut value = agent_use_unavailable_json(
        &profile,
        &preflight,
        "context-pack",
        None,
        None,
        normal_dot_codegraph_existed_before,
    );
    let staged_availability = value.get("staged_availability").cloned();
    compact_agent_use_agent_json_envelope(
        &mut value,
        &profile,
        detail_mode,
        max_output_bytes,
        staged_availability.as_ref(),
    );
    Ok(value)
}

fn context_pack_forwarded_max_output_bytes(args: &[String]) -> Option<usize> {
    let mut index = 0usize;
    while index < args.len() {
        let arg = args[index].as_str();
        if matches!(
            arg,
            "--max-output-bytes" | "--max-bytes" | "--max_output_bytes"
        ) {
            return args
                .get(index.saturating_add(1))
                .and_then(|value| parse_context_pack_max_output_bytes(value).ok());
        }
        for prefix in ["--max-output-bytes=", "--max-bytes=", "--max_output_bytes="] {
            if let Some(value) = arg.strip_prefix(prefix) {
                return parse_context_pack_max_output_bytes(value).ok();
            }
        }
        index = index.saturating_add(1);
    }
    None
}

fn enforce_agent_use_context_pack_max_output_bytes(value: &mut Value, max_output_bytes: usize) {
    for _ in 0..64 {
        if serialized_json_len(value) <= max_output_bytes {
            break;
        }
        let _ = enforce_context_agent_max_output_bytes(value, max_output_bytes);
        if compact_context_agent_staged_availability(value) {
            continue;
        }
        if compact_context_agent_db_lifecycle_read(value) {
            continue;
        }
        if compact_context_agent_patch_assist_packet_minimal(value) {
            continue;
        }
        if compact_context_agent_publish_state(value) {
            continue;
        }
        for key in [
            "fallback_evidence",
            "follow_up_queries",
            "likely_files",
            "paths",
            "proof_paths",
            "recommended_tests",
            "risks",
            "snippets",
            "active_candidate_sources",
            "staged_availability",
            "agent_use_profile_root",
            "candidate_spool_query_index_path",
            "candidate_spool_query_index_bytes",
            "candidate_spool_query_index_kind",
            "candidate_spool_query_index_record_count",
            "normal_dot_codegraph_path",
            "resolved_db",
            "repo_root",
            "symbols",
            "critical_symbols",
            "candidate_total_count",
            "candidate_omitted_count",
            "candidate_sources",
            "stale_candidate_layers",
            "blocked_labels",
            "retryable_labels",
        ] {
            if remove_context_agent_field(value, key) {
                break;
            }
        }
    }
    let output_bytes = serialized_json_len(value);
    if let Some(object) = value.as_object_mut() {
        if let Some(truncation) = object.get_mut("truncation").and_then(Value::as_object_mut) {
            truncation.insert("output_bytes".to_string(), json!(output_bytes));
        }
    }
}

fn compact_context_agent_publish_state(value: &mut Value) -> bool {
    let Some(publish_state) = value.get("publish_state").cloned() else {
        return false;
    };
    let compact = compact_agent_use_publish_state_summary(&publish_state);
    if compact == publish_state {
        return false;
    }
    if let Some(object) = value.as_object_mut() {
        object.insert("publish_state".to_string(), compact);
        return true;
    }
    false
}

fn compact_agent_use_agent_json_envelope(
    value: &mut Value,
    profile: &AgentUseProfile,
    detail_mode: AgentUseDetailMode,
    max_output_bytes: usize,
    staged_availability: Option<&Value>,
) {
    let mut truncated_sections = Vec::new();
    let mut omitted_count = 0u64;
    agent_use_ensure_required_agent_fields(value, profile);
    agent_use_dedupe_recovery_commands(value, profile, &mut omitted_count);

    if detail_mode.preserves_full_details() {
        if let Some(object) = value.as_object_mut() {
            object.insert(
                "agent_json_detail_mode".to_string(),
                json!(match detail_mode {
                    AgentUseDetailMode::Compact => "compact",
                    AgentUseDetailMode::Explain => "explain",
                    AgentUseDetailMode::Audit => "audit",
                }),
            );
        }
    } else {
        agent_use_compact_recovery_fields(
            value,
            profile,
            &mut truncated_sections,
            &mut omitted_count,
        );
        agent_use_compact_lifecycle_fields(value, &mut truncated_sections, &mut omitted_count);
        agent_use_compact_staged_availability_field(
            value,
            staged_availability,
            &mut truncated_sections,
            &mut omitted_count,
        );
        agent_use_compact_rtds_freshness_field(value, &mut truncated_sections, &mut omitted_count);
        // Preserve a minimal top-level last_delta_update_summary (status + counts)
        // rather than dropping it entirely; agents and the delta contract need
        // `last_delta_update_summary.status` after a watch/delta update.
        if let Some(summary) = value.get("last_delta_update_summary").cloned() {
            if !summary.is_null() {
                if let Some(object) = value.as_object_mut() {
                    object.insert(
                        "last_delta_update_summary".to_string(),
                        compact_agent_use_last_delta_update_summary(&summary),
                    );
                }
            }
        }
        agent_use_compact_publish_state_field(value, &mut truncated_sections, &mut omitted_count);
        agent_use_compact_read_path_metrics_field(
            value,
            &mut truncated_sections,
            &mut omitted_count,
        );
        agent_use_compact_query_results_field(value, &mut truncated_sections, &mut omitted_count);
        for key in [
            "agent_use_command",
            "agent_use_profile_name",
            "output_mode",
            "repo_source",
            "resolved_repo",
            "profile",
            "agent_use_profile",
            "db_health",
            "sqlite_sidecars",
            "agent_use_profile_root",
            "normal_dot_codegraph_path",
            "repo_root",
            "resolved_db",
            "db_exists",
            "db_created",
            "profile_parent_exists",
            "profile_parent_created",
            "candidate_spool_query_index_path",
            "candidate_spool_query_index_bytes",
            "candidate_spool_query_index_kind",
            "candidate_spool_query_index_record_count",
            "vector_runtime_path",
            "vector_audit_path",
            "scope_examples",
            "sidecar_manifests",
            "blocked_labels",
            "blockers",
            "active_candidate_sources",
            "candidate_context_truncated",
            "candidate_spool_unavailable",
            "lifecycle_decision",
            "outside_workspace_note",
            "path_access_error",
            "path_access_status",
            "files",
            "entities",
            "relation_facts",
            "source_span_facts",
            "edges",
            "source_spans",
            "languages",
        ] {
            if agent_use_remove_field(value, key) {
                truncated_sections.push(key.to_string());
                omitted_count = omitted_count.saturating_add(1);
            }
        }
    }

    let enforcement_budget = max_output_bytes
        .saturating_sub(1024)
        .max(max_output_bytes.min(MIN_CONTEXT_AGENT_MAX_OUTPUT_BYTES));
    agent_use_enforce_total_output_budget(
        value,
        enforcement_budget,
        &mut truncated_sections,
        &mut omitted_count,
    );
    if serialized_json_len(value) > max_output_bytes {
        let hard_budget = if max_output_bytes <= 4096 {
            enforcement_budget
        } else {
            max_output_bytes
        };
        agent_use_enforce_hard_agent_json_budget(
            value,
            hard_budget,
            max_output_bytes <= 4096,
            &mut truncated_sections,
            &mut omitted_count,
        );
    }
    agent_use_finalize_agent_json_budget(
        value,
        detail_mode,
        max_output_bytes,
        truncated_sections,
        omitted_count,
    );
}

fn agent_use_ensure_required_agent_fields(value: &mut Value, profile: &AgentUseProfile) {
    let Some(object) = value.as_object_mut() else {
        return;
    };
    let command = object
        .get("command")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string();
    object
        .entry("schema_version".to_string())
        .or_insert_with(|| json!(AGENT_JSON_SCHEMA_VERSION));
    if !object.contains_key("schema_name") {
        let schema_name = match command.as_str() {
            "status" => Some("status_compact_json"),
            "context-pack" | "context" => Some("context_pack_agent_json"),
            _ => None,
        };
        if let Some(schema_name) = schema_name {
            object.insert("schema_name".to_string(), json!(schema_name));
        }
    }
    object
        .entry("repo".to_string())
        .or_insert_with(|| json!(path_string(&profile.repo_root)));
    object
        .entry("db".to_string())
        .or_insert_with(|| json!(path_string(&profile.db_path)));
    object
        .entry("db_path".to_string())
        .or_insert_with(|| json!(path_string(&profile.db_path)));
    object
        .entry("db_source".to_string())
        .or_insert_with(|| json!("agent-use profile"));
    object
        .entry("external_db_used".to_string())
        .or_insert_with(|| json!(true));
    object
        .entry("profile_name".to_string())
        .or_insert_with(|| json!(profile.profile_name.clone()));
    object
        .entry("warnings".to_string())
        .or_insert_with(|| json!([]));
    object
        .entry("errors".to_string())
        .or_insert_with(|| json!([]));
    object
        .entry("public_claim".to_string())
        .or_insert_with(|| json!(false));
    object
        .entry("normal_dot_codegraph_mutated".to_string())
        .or_insert_with(|| json!(false));

    let claimable = object
        .get("claimable")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let diagnostic_only = object
        .get("diagnostic_only")
        .and_then(Value::as_bool)
        .unwrap_or(!claimable);
    let graph_proof = object
        .get("graph_proof")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let proof_status = object
        .get("proof_status")
        .and_then(Value::as_str)
        .unwrap_or(if graph_proof {
            "proof_path_found"
        } else {
            "not_graph_proof"
        })
        .to_string();
    let proof_strength = object
        .get("proof_strength")
        .and_then(Value::as_str)
        .unwrap_or(if graph_proof {
            "graph_source_verified"
        } else {
            "none"
        })
        .to_string();
    object
        .entry("graph_proof".to_string())
        .or_insert_with(|| json!(graph_proof));
    object
        .entry("proof_status".to_string())
        .or_insert_with(|| json!(proof_status));
    object
        .entry("proof_strength".to_string())
        .or_insert_with(|| json!(proof_strength));
    object.entry("claimability".to_string()).or_insert_with(|| {
        json!({
            "claimable": claimable,
            "diagnostic_only": diagnostic_only,
            "graph_proof": graph_proof,
            "proof_status": proof_status,
            "proof_strength": proof_strength,
            "graph_proof_only_from_graph_source_verification": true,
            "candidate_evidence_is_not_graph_proof": true,
            "text_evidence_is_not_graph_proof": true,
            "vector_evidence_is_not_graph_proof": true,
        })
    });
}

