#[derive(Debug, Clone)]
struct CandidateSpoolBudgetDecision {
    policy: CandidateSpoolPolicy,
    required: bool,
    requested_path: Option<PathBuf>,
    effective_path: Option<PathBuf>,
    budget_bytes: Option<u64>,
    artifact_budget_remaining_bytes: Option<u64>,
    decision: String,
    disabled_reason: Option<String>,
    warning: Option<String>,
}

impl CandidateSpoolBudgetDecision {
    fn base(options: &IndexOptions) -> Self {
        Self {
            policy: options.candidate_spool_policy,
            required: options.candidate_spool_required,
            requested_path: options.candidate_spool_path.clone(),
            effective_path: options.candidate_spool_path.clone(),
            budget_bytes: Some(options.candidate_spool_caps.global_max_bytes as u64),
            artifact_budget_remaining_bytes: None,
            decision: "candidate_spool_not_requested".to_string(),
            disabled_reason: None,
            warning: None,
        }
    }

    fn to_json(&self) -> Value {
        json!({
            "candidate_spool_policy": self.policy.as_str(),
            "candidate_spool_required": self.required,
            "candidate_spool_budget_bytes": self.budget_bytes,
            "artifact_budget_remaining_bytes": self.artifact_budget_remaining_bytes,
            "artifact_budget_decision": self.decision,
            "candidate_spool_disabled_reason": self.disabled_reason,
            "candidate_spool_warning": self.warning,
            "candidate_spool_requested_path": self.requested_path.as_ref().map(|path| path_string(path)),
            "candidate_spool_effective_path": self.effective_path.as_ref().map(|path| path_string(path)),
        })
    }
}

fn artifact_budget_bytes(options: &storage_budget::StorageBudgetOptions) -> u64 {
    (options.max_artifacts_mib * 1024.0 * 1024.0).max(0.0) as u64
}

fn apply_candidate_spool_budget_policy(
    options: &mut IndexOptions,
    budget_options: &storage_budget::StorageBudgetOptions,
    vector_options: &VectorIndexCliOptions,
) -> CandidateSpoolBudgetDecision {
    let mut decision = CandidateSpoolBudgetDecision::base(options);
    if options.candidate_spool_policy == CandidateSpoolPolicy::Off {
        decision.effective_path = None;
        decision.budget_bytes = Some(0);
        decision.decision = "candidate_spool_policy_off".to_string();
        decision.disabled_reason = Some("candidate_spool_policy_off".to_string());
        options.candidate_spool_path = None;
        options.candidate_spool_caps.global_max_bytes = 0;
        options.candidate_spool_caps.global_max_records = 0;
        return decision;
    }
    if options.candidate_spool_path.is_none() {
        decision.decision = if options.candidate_spool_required {
            "candidate_spool_required_without_path".to_string()
        } else {
            "candidate_spool_not_requested".to_string()
        };
        if options.candidate_spool_required {
            decision.disabled_reason = Some("candidate_spool_required_without_path".to_string());
        }
        return decision;
    }

    let artifact_budget = artifact_budget_bytes(budget_options);
    let runtime_reserve = if vector_options.runtime_path.is_some() {
        CANDIDATE_SPOOL_RUNTIME_RESERVE_BYTES.min((artifact_budget as usize).saturating_div(2))
    } else {
        0
    };
    let audit_reserve = if vector_options.audit_artifact_path.is_some() {
        CANDIDATE_SPOOL_AUDIT_RESERVE_BYTES.min((artifact_budget as usize).saturating_div(4))
    } else {
        0
    };
    let safety_reserve =
        CANDIDATE_SPOOL_SAFETY_RESERVE_BYTES.min((artifact_budget as usize).saturating_div(4));
    let remaining = (artifact_budget as usize)
        .saturating_sub(runtime_reserve)
        .saturating_sub(audit_reserve)
        .saturating_sub(safety_reserve);
    decision.artifact_budget_remaining_bytes = Some(remaining as u64);

    if remaining < CANDIDATE_SPOOL_MIN_USEFUL_BUDGET_BYTES {
        options.candidate_spool_caps.global_max_bytes = 0;
        options.candidate_spool_caps.global_max_records = 0;
        decision.budget_bytes = Some(0);
        decision.decision = if options.candidate_spool_required {
            "candidate_spool_required_budget_exceeded".to_string()
        } else {
            "candidate_spool_disabled_budget_exceeded".to_string()
        };
        decision.disabled_reason = Some("candidate_spool_budget_too_small".to_string());
        decision.warning = Some(
            "Candidate spool disabled because the remaining artifact budget is below the minimum useful bounded working-set threshold.".to_string(),
        );
        if !options.candidate_spool_required {
            options.candidate_spool_path = None;
            decision.effective_path = None;
        }
        return decision;
    }

    let storage_factor = if options.candidate_spool_query_index {
        CANDIDATE_SPOOL_QUERY_INDEX_STORAGE_FACTOR
    } else {
        1
    };
    let adaptive_jsonl_budget = remaining
        .saturating_div(storage_factor)
        .max(CANDIDATE_SPOOL_MIN_USEFUL_BUDGET_BYTES)
        .min(remaining);
    let original = options.candidate_spool_caps.global_max_bytes;
    let effective = original.min(adaptive_jsonl_budget);
    options.candidate_spool_caps.global_max_bytes = effective;
    decision.budget_bytes = Some(effective as u64);
    if effective < original {
        decision.decision = "candidate_spool_truncated_to_fit_artifact_budget".to_string();
        decision.warning = Some(format!(
            "Candidate spool cap reduced from {original} to {effective} bytes to leave room for required artifacts and the query index."
        ));
    } else {
        decision.decision = "candidate_spool_within_artifact_budget".to_string();
    }
    if options.candidate_spool_policy == CandidateSpoolPolicy::Audit {
        let note = "candidate_spool_policy=audit is explicit diagnostic mode; normal query/status/context-pack still treat spool records as candidate-only and do not use them as graph proof.";
        decision.warning = Some(match decision.warning.take() {
            Some(existing) => format!("{existing} {note}"),
            None => note.to_string(),
        });
    }
    decision
}

fn candidate_spool_footprint_bytes(summary: &IndexSummary) -> u64 {
    summary
        .candidate_spool
        .as_ref()
        .map(|spool| spool.spooled_bytes.saturating_add(spool.query_index_bytes))
        .unwrap_or(0)
}

fn candidate_spool_required_error_value(
    decision: &CandidateSpoolBudgetDecision,
    graph_db_claimable: bool,
    runtime_sidecar_ready: bool,
    message: impl Into<String>,
) -> Value {
    json!({
        "status": "error",
        "error": "candidate_spool_required_budget_exceeded",
        "message": message.into(),
        "candidate_spool_policy": decision.policy.as_str(),
        "candidate_spool_required": decision.required,
        "candidate_spool_budget_bytes": decision.budget_bytes,
        "artifact_budget_remaining_bytes": decision.artifact_budget_remaining_bytes,
        "artifact_budget_decision": decision.decision,
        "candidate_spool_disabled_reason": decision.disabled_reason,
        "candidate_spool_warning": decision.warning,
        "graph_db_claimable": graph_db_claimable,
        "runtime_sidecar_ready": runtime_sidecar_ready,
        "index_exit_status_reason": "candidate_spool_required_budget_exceeded",
        "public_claim": false,
    })
}

fn apply_candidate_spool_budget_json_fields(
    object: &mut serde_json::Map<String, Value>,
    summary: &IndexSummary,
    decision: &CandidateSpoolBudgetDecision,
    spool_footprint_bytes: u64,
    graph_db_claimable: bool,
    runtime_sidecar_ready: bool,
) {
    let spool = summary.candidate_spool.as_ref();
    let disabled_reason = spool
        .and_then(|spool| spool.candidate_spool_disabled_reason.clone())
        .or_else(|| decision.disabled_reason.clone());
    let warning = spool
        .and_then(|spool| spool.candidate_spool_warning.clone())
        .or_else(|| decision.warning.clone());
    let artifact_decision = spool
        .and_then(|spool| spool.artifact_budget_decision.clone())
        .unwrap_or_else(|| decision.decision.clone());
    let candidate_spool_truncated = spool
        .map(|spool| spool.candidate_spool_truncated)
        .unwrap_or(false)
        || matches!(
            artifact_decision.as_str(),
            "candidate_spool_truncated_to_fit_artifact_budget"
                | "candidate_spool_exceeds_remaining_budget"
                | "candidate_spool_disabled_budget_exceeded"
        );
    let exit_reason = if disabled_reason.is_some() {
        "indexed_candidate_spool_disabled_or_unavailable"
    } else if warning.is_some() || candidate_spool_truncated {
        "indexed_candidate_spool_warning"
    } else {
        "indexed"
    };
    let fields = [
        (
            "candidate_spool_policy",
            json!(spool
                .map(|spool| spool.candidate_spool_policy.as_str())
                .unwrap_or_else(|| decision.policy.as_str())),
        ),
        (
            "candidate_spool_required",
            json!(spool
                .map(|spool| spool.candidate_spool_required)
                .unwrap_or(decision.required)),
        ),
        (
            "candidate_spool_budget_bytes",
            json!(spool
                .map(|spool| spool.candidate_spool_budget_bytes)
                .or(decision.budget_bytes)
                .unwrap_or(0)),
        ),
        (
            "candidate_spool_written_bytes",
            json!(spool_footprint_bytes),
        ),
        (
            "candidate_spool_truncated",
            json!(candidate_spool_truncated),
        ),
        ("candidate_spool_disabled_reason", json!(disabled_reason)),
        ("candidate_spool_warning", json!(warning)),
        (
            "artifact_budget_remaining_bytes",
            json!(spool
                .and_then(|spool| spool.artifact_budget_remaining_bytes)
                .or(decision.artifact_budget_remaining_bytes)),
        ),
        ("artifact_budget_decision", json!(artifact_decision)),
        ("index_exit_status_reason", json!(exit_reason)),
        ("graph_db_claimable", json!(graph_db_claimable)),
        ("runtime_sidecar_ready", json!(runtime_sidecar_ready)),
    ];
    for (key, value) in fields {
        object.insert(key.to_string(), value);
    }
    object.insert("candidate_spool_budget".to_string(), decision.to_json());
    let mirror = [
        "candidate_spool_policy",
        "candidate_spool_required",
        "candidate_spool_budget_bytes",
        "candidate_spool_written_bytes",
        "candidate_spool_truncated",
        "candidate_spool_disabled_reason",
        "candidate_spool_warning",
        "artifact_budget_remaining_bytes",
        "artifact_budget_decision",
        "index_exit_status_reason",
        "graph_db_claimable",
        "runtime_sidecar_ready",
    ];
    let mirror_values = mirror
        .iter()
        .filter_map(|key| object.get(*key).cloned().map(|value| (*key, value)))
        .collect::<Vec<_>>();
    if let Some(summary_value) = object.get_mut("summary").and_then(Value::as_object_mut) {
        for (key, value) in mirror_values {
            summary_value.insert(key.to_string(), value);
        }
    }
}

fn parse_index_command_options(
    args: &[String],
) -> Result<
    (
        String,
        Option<PathBuf>,
        IndexOptions,
        IndexJsonOutputMode,
        storage_budget::StorageBudgetOptions,
        VectorIndexCliOptions,
    ),
    String,
> {
    let mut repo = None;
    let mut db = None;
    let mut vector_index = VectorIndexCliOptions::default();
    let mut options = IndexOptions::default();
    let mut storage_budget = storage_budget::StorageBudgetOptions::normal_self_use();
    let mut output_mode = IndexJsonOutputMode::Concise;
    let mut agent_json_requested = false;
    let mut audit_json_requested = false;
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--profile" => {
                options.profile = true;
                options.json = true;
            }
            "--json" => options.json = true,
            "--agent-json" | "--agent_json" => {
                options.json = true;
                output_mode = IndexJsonOutputMode::Agent;
                agent_json_requested = true;
            }
            "--concise" => {
                options.json = true;
                if !agent_json_requested {
                    output_mode = IndexJsonOutputMode::Concise;
                }
            }
            "--audit-json" | "--audit_json" => {
                options.json = true;
                output_mode = IndexJsonOutputMode::Audit;
                audit_json_requested = true;
            }
            "--verbose" => {
                options.profile = true;
                options.json = true;
                output_mode = IndexJsonOutputMode::Audit;
                audit_json_requested = true;
            }
            "--db" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--db requires a path".to_string());
                };
                db = Some(PathBuf::from(raw));
                options.db_lifecycle.explicit_db_path = true;
            }
            "--fresh" | "--rebuild" => {
                options.db_lifecycle.policy = DbLifecyclePolicy::FreshRebuild;
            }
            "--incremental" => {
                options.db_lifecycle.policy = DbLifecyclePolicy::IncrementalRequired;
            }
            "--fail-on-db-problem" => {
                options.db_lifecycle.policy = DbLifecyclePolicy::FailOnDbProblem;
            }
            "--allow-stale-reuse" => {
                options.db_lifecycle.policy = DbLifecyclePolicy::DiagnosticStaleReuse;
            }
            "--build-vector-index" | "--vector-runtime-sidecar" | "--vector_runtime_sidecar" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--build-vector-index requires a path".to_string());
                };
                vector_index.runtime_path = Some(PathBuf::from(raw));
                options.json = true;
            }
            "--vector-audit-artifact" | "--vector_audit_artifact" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--vector-audit-artifact requires a path".to_string());
                };
                vector_index.audit_artifact_path = Some(PathBuf::from(raw));
                options.json = true;
            }
            "--no-vector-audit" | "--no_vector_audit" => {
                vector_index.no_audit = true;
            }
            "--vector-artifact-format" | "--vector_artifact_format" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--vector-artifact-format requires a value".to_string());
                };
                vector_index.runtime_format = raw.parse::<VectorChunkArtifactFormat>()?;
                options.json = true;
            }
            "--candidate-spool" | "--emit-candidate-spool" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--candidate-spool requires a path".to_string());
                };
                options.candidate_spool_path = Some(PathBuf::from(raw));
                options.json = true;
            }
            "--candidate-spool-policy" | "--candidate_spool_policy" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err(
                        "--candidate-spool-policy requires off, bounded, or audit".to_string()
                    );
                };
                options.candidate_spool_policy = raw.parse::<CandidateSpoolPolicy>()?;
                options.json = true;
            }
            "--candidate-spool-required" | "--candidate_spool_required" => {
                options.candidate_spool_required = true;
                options.json = true;
            }
            "--candidate-spool-query-index" | "--candidate_spool_query_index" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--candidate-spool-query-index requires yes or no".to_string());
                };
                options.candidate_spool_query_index =
                    parse_index_bool(raw, "--candidate-spool-query-index")?;
                options.json = true;
            }
            "--candidate-spool-max-mib" | "--candidate_spool_max_mib" => {
                index += 1;
                let mib =
                    parse_index_positive_f64_arg(args.get(index), "--candidate-spool-max-mib")?;
                options.candidate_spool_caps.global_max_bytes =
                    (mib * 1024.0 * 1024.0).round() as usize;
            }
            "--candidate-spool-max-bytes" | "--candidate_spool_max_bytes" => {
                index += 1;
                options.candidate_spool_caps.global_max_bytes =
                    parse_index_usize_arg(args.get(index), "--candidate-spool-max-bytes")?;
            }
            "--candidate-spool-max-records" | "--candidate_spool_max_records" => {
                index += 1;
                options.candidate_spool_caps.global_max_records =
                    parse_index_usize_arg(args.get(index), "--candidate-spool-max-records")?;
            }
            "--candidate-spool-per-file-max-records" | "--candidate_spool_per_file_max_records" => {
                index += 1;
                options.candidate_spool_caps.per_file_max_records = parse_index_usize_arg(
                    args.get(index),
                    "--candidate-spool-per-file-max-records",
                )?;
            }
            "--candidate-spool-per-dir-soft-cap" | "--candidate_spool_per_dir_soft_cap" => {
                index += 1;
                options.candidate_spool_caps.per_top_level_dir_soft_cap =
                    parse_index_usize_arg(args.get(index), "--candidate-spool-per-dir-soft-cap")?;
            }
            "--candidate-spool-max-snippet-bytes" | "--candidate_spool_max_snippet_bytes" => {
                index += 1;
                options.candidate_spool_caps.max_snippet_bytes =
                    parse_index_usize_arg(args.get(index), "--candidate-spool-max-snippet-bytes")?;
            }
            "--candidate-spool-max-snippets-per-file"
            | "--candidate_spool_max_snippets_per_file" => {
                index += 1;
                options.candidate_spool_caps.max_snippets_per_file_packet = parse_index_usize_arg(
                    args.get(index),
                    "--candidate-spool-max-snippets-per-file",
                )?;
            }
            "--candidate-spool-max-symbols-per-file" | "--candidate_spool_max_symbols_per_file" => {
                index += 1;
                options.candidate_spool_caps.max_symbols_per_file_packet = parse_index_usize_arg(
                    args.get(index),
                    "--candidate-spool-max-symbols-per-file",
                )?;
            }
            "--early-candidates" => {
                options.json = true;
            }
            "--workers" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--workers requires a value".to_string());
                };
                let workers = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --workers value: {raw}"))?;
                if workers == 0 {
                    return Err("--workers must be at least 1".to_string());
                }
                options.worker_count = Some(workers);
            }
            "--storage-mode" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--storage-mode requires a value".to_string());
                };
                options.storage_mode = raw.parse::<StorageMode>()?;
            }
            "--build-mode" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--build-mode requires a value".to_string());
                };
                options.build_mode = raw.parse::<IndexBuildMode>()?;
            }
            "--include-ignored" => options.scope.include_ignored = true,
            "--include" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--include requires a pattern".to_string());
                };
                options.scope.include_patterns.push(raw.to_string());
            }
            "--exclude" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--exclude requires a pattern".to_string());
                };
                options.scope.exclude_patterns.push(raw.to_string());
            }
            "--no-default-excludes" => options.scope.no_default_excludes = true,
            "--respect-gitignore" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--respect-gitignore requires true or false".to_string());
                };
                options.scope.respect_gitignore = parse_index_bool(raw, "--respect-gitignore")?;
            }
            "--explain-scope" => options.scope.explain_scope = true,
            "--print-included" => options.scope.print_included = true,
            "--print-excluded" => options.scope.print_excluded = true,
            value => {
                if storage_budget::parse_storage_budget_flag(args, &mut index, &mut storage_budget)?
                {
                    index += 1;
                    continue;
                }
                if value.starts_with('-') {
                    return Err(format!("unknown index option: {value}"));
                }
                if repo.is_some() {
                    return Err(format!("unexpected index argument: {value}"));
                }
                repo = Some(value.to_string());
            }
        }
        index += 1;
    }
    if !agent_json_requested
        && (audit_json_requested || options.profile || options.scope.has_print_or_explain())
    {
        output_mode = IndexJsonOutputMode::Audit;
    }
    if vector_index.no_audit && vector_index.audit_artifact_path.is_some() {
        return Err(
            "--no-vector-audit cannot be combined with --vector-audit-artifact".to_string(),
        );
    }
    if vector_index.audit_artifact_path.is_some() && vector_index.runtime_path.is_none() {
        return Err(
            "--vector-audit-artifact requires --build-vector-index or --vector-runtime-sidecar"
                .to_string(),
        );
    }
    Ok((
        repo.ok_or_else(|| {
            "Usage: codegraph-mcp index <repo> [--db <path>] [--fresh|--rebuild] [--incremental] [--fail-on-db-problem] [--allow-stale-reuse] [--build-vector-index <runtime_path>|--vector-runtime-sidecar <runtime_path>] [--vector-audit-artifact <audit_path>] [--no-vector-audit] [--vector-artifact-format compact_json|pretty_json] [--candidate-spool <path>] [--candidate-spool-policy off|bounded|audit] [--candidate-spool-max-mib <n>] [--candidate-spool-max-bytes <n>] [--candidate-spool-max-records <n>] [--candidate-spool-required] [--candidate-spool-query-index yes|no] [--early-candidates] [--profile] [--json|--agent-json|--audit-json] [--verbose] [--workers <n>] [--storage-mode <proof|audit|debug>] [--build-mode <proof-build-only|proof-build-plus-validation>] [--max-db-mib <n>] [--max-artifacts-mib <n>] [--min-free-disk-gib <n>] [--extended] [--stress-corpus <name>] [--include-ignored] [--include <pattern>] [--exclude <pattern>] [--no-default-excludes] [--respect-gitignore <true|false>] [--explain-scope] [--print-included] [--print-excluded]\nScope: default repo scope plus explicit include overrides; --include is not a restrictive only-these-globs filter.".to_string()
        })?,
        db,
        options,
        output_mode,
        storage_budget,
        vector_index,
    ))
}

fn parse_index_bool(raw: &str, flag: &str) -> Result<bool, String> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "true" | "1" | "yes" | "on" => Ok(true),
        "false" | "0" | "no" | "off" => Ok(false),
        _ => Err(format!("{flag} requires true or false, got {raw}")),
    }
}

fn parse_index_usize_arg(raw: Option<&String>, flag: &str) -> Result<usize, String> {
    let Some(raw) = raw else {
        return Err(format!("{flag} requires a value"));
    };
    let value = raw
        .parse::<usize>()
        .map_err(|_| format!("invalid {flag} value: {raw}"))?;
    if value == 0 {
        return Err(format!("{flag} must be at least 1"));
    }
    Ok(value)
}

fn parse_index_positive_f64_arg(raw: Option<&String>, flag: &str) -> Result<f64, String> {
    let Some(raw) = raw else {
        return Err(format!("{flag} requires a value"));
    };
    let value = raw
        .parse::<f64>()
        .map_err(|_| format!("invalid {flag} value: {raw}"))?;
    if !value.is_finite() || value <= 0.0 {
        return Err(format!("{flag} must be greater than zero"));
    }
    Ok(value)
}

fn parse_watch_options(args: &[String]) -> Result<WatchOptions, String> {
    let mut repo = None;
    let mut db = None;
    let mut debounce = Duration::from_millis(250);
    let mut once = false;
    let mut changed_paths = Vec::new();
    let mut index = 0;

    while index < args.len() {
        match args[index].as_str() {
            "--debounce-ms" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--debounce-ms requires a value".to_string());
                };
                let millis = value
                    .parse::<u64>()
                    .map_err(|_| format!("invalid debounce milliseconds: {value}"))?;
                debounce = Duration::from_millis(millis);
            }
            "--db" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--db requires a path".to_string());
                };
                db = Some(PathBuf::from(value));
            }
            "--once" => once = true,
            "--changed" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--changed requires a path".to_string());
                };
                changed_paths.push(PathBuf::from(value));
            }
            value if value.starts_with('-') => {
                return Err(format!("unknown watch option: {value}"));
            }
            value => {
                if repo.is_some() {
                    return Err(format!("unexpected watch argument: {value}"));
                }
                repo = Some(PathBuf::from(value));
            }
        }
        index += 1;
    }

    Ok(WatchOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        db,
        debounce,
        once,
        changed_paths,
    })
}

fn parse_ui_options(args: &[String]) -> Result<UiOptions, String> {
    let mut repo = None;
    let mut host = "127.0.0.1".to_string();
    let mut port = 7878_u16;
    let mut index = 0;

    while index < args.len() {
        match args[index].as_str() {
            "--host" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--host requires a value".to_string());
                };
                host = value.clone();
            }
            "--port" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--port requires a value".to_string());
                };
                port = value
                    .parse::<u16>()
                    .map_err(|_| format!("invalid UI port: {value}"))?;
            }
            value if value.starts_with('-') => {
                return Err(format!("unknown serve-ui option: {value}"));
            }
            value => {
                if repo.is_some() {
                    return Err(format!("unexpected serve-ui argument: {value}"));
                }
                repo = Some(PathBuf::from(value));
            }
        }
        index += 1;
    }

    if !is_local_host(&host) {
        return Err(format!(
            "serve-ui is local-only by default; refusing host {host}"
        ));
    }

    Ok(UiOptions {
        repo: repo.unwrap_or_else(|| PathBuf::from(".")),
        host,
        port,
    })
}

fn parse_bench_options(args: &[String]) -> Result<BenchOptions, String> {
    let mut baselines = Vec::new();
    let mut format = BenchReportFormat::Json;
    let mut output = None;
    let mut index = 0;

    while index < args.len() {
        match args[index].as_str() {
            "--baseline" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--baseline requires a value".to_string());
                };
                for value in raw.split(',').filter(|value| !value.trim().is_empty()) {
                    baselines.push(
                        value
                            .parse::<BaselineMode>()
                            .map_err(|error| error.to_string())?,
                    );
                }
            }
            "--format" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--format requires json or markdown".to_string());
                };
                format = match raw.trim().to_ascii_lowercase().as_str() {
                    "json" => BenchReportFormat::Json,
                    "markdown" | "md" => BenchReportFormat::Markdown,
                    other => return Err(format!("unknown benchmark report format: {other}")),
                };
            }
            "--output" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--output requires a path".to_string());
                };
                output = Some(PathBuf::from(raw));
            }
            value => return Err(format!("unknown benchmark option: {value}")),
        }
        index += 1;
    }

    Ok(BenchOptions {
        baselines,
        format,
        output,
    })
}

fn parse_graph_truth_gate_options(args: &[String]) -> Result<GraphTruthGateOptions, String> {
    let mut options = codegraph_bench::default_graph_truth_gate_options();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--cases" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--cases requires a path".to_string());
                };
                options.cases = PathBuf::from(value);
            }
            "--fixture-root" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--fixture-root requires a path".to_string());
                };
                options.fixture_root = PathBuf::from(value);
            }
            "--out-json" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-json requires a path".to_string());
                };
                options.out_json = PathBuf::from(value);
            }
            "--out-md" | "--out-markdown" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-md requires a path".to_string());
                };
                options.out_md = PathBuf::from(value);
            }
            "--fail-on-forbidden" => {
                options.fail_on_forbidden = true;
            }
            "--fail-on-missing-source-span" => {
                options.fail_on_missing_source_span = true;
            }
            "--fail-on-unresolved-exact" => {
                options.fail_on_unresolved_exact = true;
            }
            "--fail-on-derived-without-provenance" => {
                options.fail_on_derived_without_provenance = true;
            }
            "--fail-on-test-mock-production-leak" => {
                options.fail_on_test_mock_production_leak = true;
            }
            "--update-mode" => {
                options.update_mode = true;
            }
            "--keep-workdirs" => {
                options.keep_workdirs = true;
            }
            "--verbose" => {
                options.verbose = true;
            }
            value => return Err(format!("unknown graph-truth option: {value}")),
        }
        index += 1;
    }
    Ok(options)
}

fn parse_context_packet_gate_options(args: &[String]) -> Result<ContextPacketGateOptions, String> {
    let mut options = codegraph_bench::default_context_packet_gate_options();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--cases" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--cases requires a path".to_string());
                };
                options.cases = PathBuf::from(value);
            }
            "--fixture-root" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--fixture-root requires a path".to_string());
                };
                options.fixture_root = PathBuf::from(value);
            }
            "--out-json" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-json requires a path".to_string());
                };
                options.out_json = PathBuf::from(value);
            }
            "--out-md" | "--out-markdown" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-md requires a path".to_string());
                };
                options.out_md = PathBuf::from(value);
            }
            "--top-k" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--top-k requires a positive integer".to_string());
                };
                options.top_k = value
                    .parse::<usize>()
                    .map_err(|error| format!("invalid --top-k: {error}"))?;
                if options.top_k == 0 {
                    return Err("--top-k must be greater than zero".to_string());
                }
            }
            "--budget" | "--token-budget" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--budget requires a positive integer".to_string());
                };
                options.token_budget = value
                    .parse::<usize>()
                    .map_err(|error| format!("invalid --budget: {error}"))?;
                if options.token_budget == 0 {
                    return Err("--budget must be greater than zero".to_string());
                }
            }
            value => return Err(format!("unknown context-packet option: {value}")),
        }
        index += 1;
    }
    Ok(options)
}

fn parse_retrieval_ablation_options(args: &[String]) -> Result<RetrievalAblationOptions, String> {
    let mut options = codegraph_bench::default_retrieval_ablation_options();
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--cases" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--cases requires a path".to_string());
                };
                options.cases = PathBuf::from(value);
            }
            "--fixture-root" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--fixture-root requires a path".to_string());
                };
                options.fixture_root = PathBuf::from(value);
            }
            "--out-json" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-json requires a path".to_string());
                };
                options.out_json = PathBuf::from(value);
            }
            "--out-md" | "--out-markdown" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--out-md requires a path".to_string());
                };
                options.out_md = PathBuf::from(value);
            }
            "--top-k" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--top-k requires a positive integer".to_string());
                };
                options.top_k = value
                    .parse::<usize>()
                    .map_err(|error| format!("invalid --top-k: {error}"))?;
            }
            "--mode" | "--modes" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err("--mode requires a retrieval-ablation mode".to_string());
                };
                for raw in value.split(',') {
                    options.modes.push(
                        raw.parse::<RetrievalAblationMode>()
                            .map_err(|error| error.to_string())?,
                    );
                }
            }
            value => return Err(format!("unknown retrieval-ablation option: {value}")),
        }
        index += 1;
    }
    Ok(options)
}

fn parse_two_layer_bench_options(args: &[String]) -> Result<TwoLayerBenchOptions, String> {
    let mut options = codegraph_bench::default_two_layer_bench_options();
    let mut index = 0usize;

    while index < args.len() {
        match args[index].as_str() {
            "--run-id" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--run-id requires a value".to_string());
                };
                options.run_id = Some(raw.clone());
            }
            "--timeout-ms" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--timeout-ms requires a non-negative integer".to_string());
                };
                options.timeout_ms = raw
                    .parse::<u64>()
                    .map_err(|_| format!("invalid --timeout-ms value: {raw}"))?
                    .min(codegraph_bench::MAX_BENCH_TASK_MS);
            }
            "--top-k" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--top-k requires a positive integer".to_string());
                };
                options.top_k = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --top-k value: {raw}"))?;
                if options.top_k == 0 {
                    return Err("--top-k must be greater than zero".to_string());
                }
            }
            "--competitor-bin" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--competitor-bin requires a path".to_string());
                };
                options.competitor_executable = Some(PathBuf::from(raw));
            }
            "--autoresearch-repo" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--autoresearch-repo requires a path".to_string());
                };
                options.autoresearch_repo = Some(PathBuf::from(raw));
            }
            "--skip-autoresearch" => {
                options.include_autoresearch = false;
            }
            "--fake-agent" | "--dry-run" => {
                options.fake_agent = true;
                options.dry_run = true;
            }
            "--run-root" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--run-root requires a path".to_string());
                };
                let run_root = PathBuf::from(raw);
                if !run_root
                    .components()
                    .any(|component| component.as_os_str() == "codegraph-bench-runs")
                {
                    return Err(
                        "--run-root must be under target/codegraph-bench-runs/<run_id>".to_string(),
                    );
                }
                options.run_root = Some(run_root);
            }
            value => return Err(format!("unknown two-layer benchmark option: {value}")),
        }
        index += 1;
    }

    Ok(options)
}

fn parse_trace_append_options(args: &[String]) -> Result<TraceAppendOptions, String> {
    let mut repo = PathBuf::from(".");
    let mut repo_id = None;
    let mut trace_root = PathBuf::from(DEFAULT_TRACE_ROOT);
    let mut run_id = None;
    let mut task_id = None;
    let mut event_type = None;
    let mut trace_id = None;
    let mut tool = None;
    let mut status = None;
    let mut actor = None;
    let mut action_kind = None;
    let mut result_status = None;
    let mut latency_ms = 0u128;
    let mut token_estimate = None;
    let mut evidence_refs = Vec::new();
    let mut edited_files = Vec::new();
    let mut test_command = None;
    let mut test_status = None;
    let mut input = None;
    let mut output = None;
    let mut error = None;
    let mut index = 0usize;

    while index < args.len() {
        match args[index].as_str() {
            "--repo" => {
                index += 1;
                repo = PathBuf::from(required_cli_value(args, index, "--repo")?);
            }
            "--repo-id" => {
                index += 1;
                repo_id = Some(required_cli_value(args, index, "--repo-id")?.to_string());
            }
            "--trace-root" => {
                index += 1;
                trace_root = PathBuf::from(required_cli_value(args, index, "--trace-root")?);
            }
            "--run-id" => {
                index += 1;
                run_id = Some(required_cli_value(args, index, "--run-id")?.to_string());
            }
            "--task-id" => {
                index += 1;
                task_id = Some(required_cli_value(args, index, "--task-id")?.to_string());
            }
            "--event-type" => {
                index += 1;
                let raw = required_cli_value(args, index, "--event-type")?;
                event_type = Some(
                    raw.parse::<TraceEventType>()
                        .map_err(|error| error.to_string())?,
                );
            }
            "--trace-id" => {
                index += 1;
                trace_id = Some(required_cli_value(args, index, "--trace-id")?.to_string());
            }
            "--tool" => {
                index += 1;
                tool = Some(required_cli_value(args, index, "--tool")?.to_string());
            }
            "--status" => {
                index += 1;
                status = Some(required_cli_value(args, index, "--status")?.to_string());
            }
            "--actor" => {
                index += 1;
                actor = Some(required_cli_value(args, index, "--actor")?.to_string());
            }
            "--action-kind" => {
                index += 1;
                action_kind = Some(required_cli_value(args, index, "--action-kind")?.to_string());
            }
            "--result-status" => {
                index += 1;
                result_status =
                    Some(required_cli_value(args, index, "--result-status")?.to_string());
            }
            "--latency-ms" => {
                index += 1;
                let raw = required_cli_value(args, index, "--latency-ms")?;
                latency_ms = raw
                    .parse::<u128>()
                    .map_err(|_| format!("invalid --latency-ms value: {raw}"))?;
            }
            "--token-estimate" => {
                index += 1;
                token_estimate = Some(parse_token_estimate(required_cli_value(
                    args,
                    index,
                    "--token-estimate",
                )?));
            }
            "--evidence-ref" => {
                index += 1;
                evidence_refs.push(required_cli_value(args, index, "--evidence-ref")?.to_string());
            }
            "--edited-file" => {
                index += 1;
                edited_files.push(required_cli_value(args, index, "--edited-file")?.to_string());
            }
            "--test-command" => {
                index += 1;
                test_command = Some(required_cli_value(args, index, "--test-command")?.to_string());
            }
            "--test-status" => {
                index += 1;
                test_status = Some(required_cli_value(args, index, "--test-status")?.to_string());
            }
            "--input-json" => {
                index += 1;
                input = Some(parse_json_arg(required_cli_value(
                    args,
                    index,
                    "--input-json",
                )?)?);
            }
            "--output-json" => {
                index += 1;
                output = Some(parse_json_arg(required_cli_value(
                    args,
                    index,
                    "--output-json",
                )?)?);
            }
            "--error" => {
                index += 1;
                error = Some(required_cli_value(args, index, "--error")?.to_string());
            }
            value => return Err(format!("unknown trace append option: {value}")),
        }
        index += 1;
    }

    let event = TraceAppendEvent {
        event_type: event_type.ok_or_else(|| "--event-type is required".to_string())?,
        trace_id: trace_id.unwrap_or_else(|| "unknown".to_string()),
        tool: tool.unwrap_or_else(|| "unknown".to_string()),
        status: status.unwrap_or_else(|| "unknown".to_string()),
        actor,
        action_kind,
        result_status,
        latency_ms,
        token_estimate,
        evidence_refs: (!evidence_refs.is_empty()).then(|| json!(evidence_refs)),
        edited_files: (!edited_files.is_empty()).then(|| json!(edited_files)),
        test_command,
        test_status,
        input,
        output,
        error,
    };
    Ok(TraceAppendOptions {
        repo,
        repo_id,
        trace_root,
        run_id,
        task_id,
        event,
    })
}

fn parse_trace_replay_options(args: &[String]) -> Result<PathBuf, String> {
    let mut events_path = None;
    let mut trace_root = PathBuf::from(DEFAULT_TRACE_ROOT);
    let mut run_id = None;
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--events" => {
                index += 1;
                events_path = Some(PathBuf::from(required_cli_value(args, index, "--events")?));
            }
            "--trace-root" => {
                index += 1;
                trace_root = PathBuf::from(required_cli_value(args, index, "--trace-root")?);
            }
            "--run-id" => {
                index += 1;
                run_id = Some(required_cli_value(args, index, "--run-id")?.to_string());
            }
            value => return Err(format!("unknown trace replay option: {value}")),
        }
        index += 1;
    }
    events_path
        .or_else(|| run_id.map(|id| trace_root.join(id).join("events.jsonl")))
        .ok_or_else(|| "trace replay requires --events or --run-id".to_string())
}

fn required_cli_value<'a>(args: &'a [String], index: usize, flag: &str) -> Result<&'a str, String> {
    args.get(index)
        .map(String::as_str)
        .ok_or_else(|| format!("{flag} requires a value"))
}

fn parse_json_arg(raw: &str) -> Result<Value, String> {
    serde_json::from_str(raw).map_err(|error| format!("invalid JSON argument: {error}"))
}

fn parse_token_estimate(raw: &str) -> Value {
    if raw.eq_ignore_ascii_case("unknown") {
        json!("unknown")
    } else {
        raw.parse::<u64>()
            .map(Value::from)
            .unwrap_or_else(|_| json!({"kind": "character_estimate", "value": raw}))
    }
}

fn parse_synthetic_index_options(args: &[String]) -> Result<SyntheticIndexOptions, String> {
    let mut output_dir = None;
    let mut files = 250usize;
    let mut storage_budget = storage_budget::StorageBudgetOptions::fixture_smoke();
    let mut index = 0usize;

    while index < args.len() {
        match args[index].as_str() {
            "--output-dir" | "--output" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--output-dir requires a path".to_string());
                };
                output_dir = Some(PathBuf::from(raw));
            }
            "--files" => {
                index += 1;
                let Some(raw) = args.get(index) else {
                    return Err("--files requires a positive integer".to_string());
                };
                files = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --files value: {raw}"))?;
                if files == 0 {
                    return Err("--files must be greater than zero".to_string());
                }
            }
            value => {
                if storage_budget::parse_storage_budget_flag(args, &mut index, &mut storage_budget)?
                {
                    index += 1;
                    continue;
                }
                return Err(format!("unknown synthetic-index option: {value}"));
            }
        }
        index += 1;
    }

    Ok(SyntheticIndexOptions {
        output_dir: output_dir.ok_or_else(|| {
            "Usage: codegraph-mcp bench synthetic-index --output-dir <dir> [--files <n>]"
                .to_string()
        })?,
        files,
        storage_budget,
    })
}

fn parse_update_integrity_harness_options(
    args: &[String],
) -> Result<UpdateIntegrityHarnessOptions, String> {
    let mut iterations = 20usize;
    let mut autoresearch_iterations = 1usize;
    let mut workers = 4usize;
    let mut medium_files = 48usize;
    let mut mode = UpdateBenchmarkMode::Fast;
    let mut loop_kind = UpdateLoopKind::Combined;
    let mut timeout_ms = None;
    let mut out_json = PathBuf::from("reports")
        .join("audit")
        .join("artifacts")
        .join("autoresearch_update_repro_fix.json");
    let mut out_md = PathBuf::from("reports")
        .join("audit")
        .join("autoresearch_update_repro_fix.md");
    let mut workdir = PathBuf::from("reports")
        .join("audit")
        .join("artifacts")
        .join("update_integrity_harness");
    let mut skip_autoresearch = false;
    let mut only_autoresearch = false;
    let mut autoresearch_repo = std::env::var_os("CODEGRAPH_AUTORESEARCH_REPO")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("..").join("autoresearch-codexlab"));
    let mut autoresearch_seed_db = None;
    let mut storage_budget = storage_budget::StorageBudgetOptions::normal_self_use();
    let mut index = 0;

    while index < args.len() {
        match args[index].as_str() {
            "--iterations" => {
                index += 1;
                let raw = args
                    .get(index)
                    .ok_or_else(|| "--iterations requires a positive integer".to_string())?;
                iterations = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --iterations value: {raw}"))?;
                if iterations == 0 {
                    return Err("--iterations must be greater than zero".to_string());
                }
            }
            "--autoresearch-iterations" => {
                index += 1;
                let raw = args.get(index).ok_or_else(|| {
                    "--autoresearch-iterations requires a positive integer".to_string()
                })?;
                autoresearch_iterations = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --autoresearch-iterations value: {raw}"))?;
            }
            "--workers" => {
                index += 1;
                let raw = args
                    .get(index)
                    .ok_or_else(|| "--workers requires a positive integer".to_string())?;
                workers = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --workers value: {raw}"))?;
                if workers == 0 {
                    return Err("--workers must be greater than zero".to_string());
                }
            }
            "--medium-files" => {
                index += 1;
                let raw = args
                    .get(index)
                    .ok_or_else(|| "--medium-files requires a positive integer".to_string())?;
                medium_files = raw
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --medium-files value: {raw}"))?;
                if medium_files < 2 {
                    return Err("--medium-files must be at least 2".to_string());
                }
            }
            "--mode" => {
                index += 1;
                let raw = args.get(index).ok_or_else(|| {
                    "--mode requires update-fast, update-validated, or update-debug".to_string()
                })?;
                mode = UpdateBenchmarkMode::parse(raw)?;
            }
            "--loop-kind" | "--loop" => {
                index += 1;
                let raw = args.get(index).ok_or_else(|| {
                    "--loop-kind requires combined, repeat-fast, or update-fast".to_string()
                })?;
                loop_kind = UpdateLoopKind::parse(raw)?;
            }
            "--timeout-ms" => {
                index += 1;
                let raw = args
                    .get(index)
                    .ok_or_else(|| "--timeout-ms requires a positive integer".to_string())?;
                let parsed = raw
                    .parse::<u64>()
                    .map_err(|_| format!("invalid --timeout-ms value: {raw}"))?;
                if parsed == 0 {
                    return Err("--timeout-ms must be greater than zero".to_string());
                }
                timeout_ms = Some(parsed);
            }
            "--out-json" => {
                index += 1;
                out_json = PathBuf::from(
                    args.get(index)
                        .ok_or_else(|| "--out-json requires a path".to_string())?,
                );
            }
            "--out-md" => {
                index += 1;
                out_md = PathBuf::from(
                    args.get(index)
                        .ok_or_else(|| "--out-md requires a path".to_string())?,
                );
            }
            "--workdir" => {
                index += 1;
                workdir = PathBuf::from(
                    args.get(index)
                        .ok_or_else(|| "--workdir requires a path".to_string())?,
                );
            }
            "--skip-autoresearch" => {
                skip_autoresearch = true;
            }
            "--only-autoresearch" => {
                only_autoresearch = true;
            }
            "--autoresearch-repo" => {
                index += 1;
                autoresearch_repo = PathBuf::from(
                    args.get(index)
                        .ok_or_else(|| "--autoresearch-repo requires a path".to_string())?,
                );
            }
            "--autoresearch-seed-db" => {
                index += 1;
                autoresearch_seed_db =
                    Some(PathBuf::from(args.get(index).ok_or_else(|| {
                        "--autoresearch-seed-db requires a path".to_string()
                    })?));
            }
            value => {
                if storage_budget::parse_storage_budget_flag(args, &mut index, &mut storage_budget)?
                {
                    index += 1;
                    continue;
                }
                return Err(format!("unknown update-integrity option: {value}"));
            }
        }
        index += 1;
    }
    if skip_autoresearch && only_autoresearch {
        return Err("--only-autoresearch cannot be combined with --skip-autoresearch".to_string());
    }

    Ok(UpdateIntegrityHarnessOptions {
        iterations,
        autoresearch_iterations,
        workers,
        medium_files,
        mode,
        loop_kind,
        timeout_ms,
        out_json: absolute_cli_path(&out_json)?,
        out_md: absolute_cli_path(&out_md)?,
        workdir: absolute_cli_path(&workdir)?,
        skip_autoresearch,
        only_autoresearch,
        autoresearch_repo: absolute_cli_path(&autoresearch_repo)?,
        autoresearch_seed_db: autoresearch_seed_db
            .as_deref()
            .map(absolute_cli_path)
            .transpose()?,
        storage_budget,
    })
}

