        assert_eq!(config["mcp_startup_auto_index"].as_bool(), Some(false));
        assert_eq!(config["auto_index_on_startup"].as_bool(), Some(false));
        assert_eq!(config["safe_read_only_startup"].as_bool(), Some(true));
